@WebMvcTest(OrderController.class)
class OrderControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private OrderService orderService;  // Service not loaded, must mock

    @Test
    void shouldReturnOrderById() throws Exception {
        var order = new Order(1L, "Laptop", 999.99);
        when(orderService.findById(1L)).thenReturn(Optional.of(order));

        mockMvc.perform(get("/api/orders/1"))
               .andExpect(status().isOk())  // HTTP 200
               .andExpect(jsonPath("$.id").value(1))
               .andExpect(jsonPath("$.item").value("Laptop"));
    }
}

@WebMvcTest(ProductController.class)
class ProductControllerTest {

    @Autowired
    private MockMvc mockMvc;  // Injected by Spring

    @MockBean
    private ProductService productService;  // Must mock the service

    @Test
    void shouldReturnProductWhenExists() throws Exception {
        // Arrange: stub the service
        var product = new Product(42L, "Keyboard", 79.99);
        when(productService.getProduct(42L)).thenReturn(Optional.of(product));

        // Act & Assert: perform request and check response
        mockMvc.perform(get("/api/products/42"))
               .andExpect(status().isOk())  // HTTP 200
               .andExpect(jsonPath("$.id").value(42))
               .andExpect(jsonPath("$.name").value("Keyboard"))
               .andExpect(jsonPath("$.price").value(79.99));
    }
}

@WebMvcTest(UserController.class)
class UserControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private UserService userService;  // Required: controller injects this

    @MockBean
    private EmailValidator emailValidator;  // Required: custom component

    @Test
    void shouldCreateUser() throws Exception {
        var user = new User(1L, "alice@example.com");
        when(emailValidator.isValid("alice@example.com")).thenReturn(true);
        when(userService.create(any(User.class))).thenReturn(user);

        mockMvc.perform(post("/api/users")
               .contentType(APPLICATION_JSON)
               .content("{\"email\":\"alice@example.com\"}"))
               .andExpect(status().isCreated());
    }
}

@WebMvcTest(OrderController.class)
class OrderControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;  // For JSON serialization

    @MockBean
    private OrderService orderService;

    @Test
    void shouldCreateOrderSuccessfully() throws Exception {
        var request = new CreateOrderRequest("Laptop", 2);
        var savedOrder = new Order(1L, "Laptop", 2, 1999.98);
        when(orderService.createOrder(any())).thenReturn(savedOrder);

        String json = objectMapper.writeValueAsString(request);

        mockMvc.perform(post("/api/orders")
               .contentType(APPLICATION_JSON)  // Required for @RequestBody
               .content(json))
               .andExpect(status().isCreated())
               .andExpect(jsonPath("$.id").value(1));
    }
}

@WebMvcTest(OrderController.class)
class OrderControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private OrderService orderService;

    @Test
    void shouldReturn404WhenOrderNotFound() throws Exception {
        // Stub service to throw exception
        when(orderService.findById(999L))
            .thenThrow(new ResourceNotFoundException("Order not found"));

        mockMvc.perform(get("/api/orders/999"))
               .andExpect(status().isNotFound())  // HTTP 404
               .andExpect(jsonPath("$.message").value("Order not found"));
    }
}

// Required: ControllerAdvice to map exception to 404
@ControllerAdvice
class GlobalExceptionHandler {
    @ExceptionHandler(ResourceNotFoundException.class)
    ResponseEntity<ErrorResponse> handle(ResourceNotFoundException ex) {
        return ResponseEntity.status(NOT_FOUND)
            .body(new ErrorResponse(ex.getMessage()));
    }
}

@WebMvcTest(CustomerController.class)
class CustomerControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private CustomerService customerService;

    @Test
    void shouldReturnCustomerWithNestedAddress() throws Exception {
        var customer = new Customer(1L, "Alice", new Address("NY", "10001"));
        when(customerService.findById(1L)).thenReturn(Optional.of(customer));

        mockMvc.perform(get("/api/customers/1"))
               .andExpect(status().isOk())
               .andExpect(jsonPath("$.id").value(1))  // Root field
               .andExpect(jsonPath("$.name").value("Alice"))
               .andExpect(jsonPath("$.address.city").value("NY"))  // Nested
               .andExpect(jsonPath("$.address.zipCode").value("10001"));
    }
}

